records = model.search([('expiration_date', '<=', datetime.date.today()), ('is_expired', '=', False), ('points', '>', 0)])
for r in records:
    model.create({
        'partner_id': r.partner_id.id,
        'company_id': r.company_id.id,
        'transaction_type': 'expire_expired',
        'points': -abs(r.points),
        'notes': f"Expired unredeemed points from transaction {r.name}"
    })
    r.write({'is_expired': True})
